import random

def get_player_choice():
    """Get a valid player choice (rock, paper, scissors)."""
    while True:
        player_choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if player_choice in ["rock", "paper", "scissors"]:
            return player_choice
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_choice():
    """Get a random computer choice (rock, paper, scissors)."""
    return random.choice(["rock", "paper", "scissors"])

def determine_winner(player_choice, computer_choice):
    """Determine the winner based on the game's rules."""
    if player_choice == computer_choice:
        return "It's a tie!"
    elif (player_choice == "rock" and computer_choice == "scissors") or \
         (player_choice == "paper" and computer_choice == "rock") or \
         (player_choice == "scissors" and computer_choice == "paper"):
        return f"{player_choice} beats {computer_choice}, player {get_player_number()} wins!"
    else:
        return f"{computer_choice} beats {player_choice}, computer wins!"

def get_player_number():
    """Get the player number (1 or 2)."""
    while True:
        try:
            player_number = int(input("Enter your number (1 or 2): "))
            if 1 <= player_number <= 2:
                return player_number
            else:
                print("Invalid input. Please enter 1 or 2.")
        except ValueError:
            print("Invalid input. Please enter a number.")

def play_game():
    """Play a single game of Rock, Paper, Scissors."""
    player_number = get_player_number()

    print(f"Player {player_number} makes their choice...")
    player_choice = get_player_choice()

    computer_choice = get_computer_choice()
    print(f"Computer chooses {computer_choice}...")

    winner = determine_winner(player_choice, computer_choice)
    print(winner)

if __name__ == "__main__":
    play_game()
```
This program defines several functions to handle different aspects of the game, such as getting player and computer choices, determining the winner, and getting the player number. The `play_game` function calls these functions to play a single game of Rock, Paper, Scissors.
